// Writes src/index.ts, re-exporting every type ts-rs generated into src/generated/.
// The generated files come from `cargo test -p imperium-protocol`; index.ts is not checked in.
import { readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const src = join(dirname(fileURLToPath(import.meta.url)), "..", "src");
const names = readdirSync(join(src, "generated"))
  .filter((file) => file.endsWith(".ts"))
  .map((file) => file.slice(0, -".ts".length))
  .sort();

const lines = [
  "// Generated by scripts/generate-index.mjs. Do not edit.",
  ...names.map((name) => `export type { ${name} } from "./generated/${name}";`),
  "",
];
writeFileSync(join(src, "index.ts"), lines.join("\n"));
